#!/usr/bin/env python3
"""Apply optimize_images patch manually to BUILD.gn file."""
import sys
import os

def apply_patch(build_gn_path):
    """Apply optimize_images patch to BUILD.gn file."""
    if not os.path.exists(build_gn_path):
        print(f"ERROR: File not found: {build_gn_path}")
        return 1
    
    with open(build_gn_path, 'r') as f:
        content = f.read()
    
    # Add import after line 5 (after import("//build/timestamp.gni"))
    if 'import("//ui/webui/resources/tools/build_webui.gni")' not in content:
        content = content.replace(
            'import("//build/timestamp.gni")',
            'import("//build/timestamp.gni")\nimport("//ui/webui/resources/tools/build_webui.gni")'
        )
    
    # Wrap optimize_images in if(optimize_webui) condition
    if 'if (optimize_webui) {' not in content:
        # Find the end of generate_css_vars and add the if condition before optimize_images
        content = content.replace(
            '}\n\nnode_action("optimize_images") {',
            '}\n\n# Only optimize images if optimize_webui is enabled (Debian uses optimize_webui=false)\n# When disabled, create a stub action that declares outputs without optimization\nif (optimize_webui) {\nnode_action("optimize_images") {'
        )
        
        # Find the end of optimize_images node_action and add else block
        import re
        # Match the closing brace of optimize_images node_action (after metadata block)
        # Look for the pattern: closing brace with proper indentation followed by blank line
        pattern = r'(  \}\n)\n(devtools_pre_built|node_action|source_set|executable|group|$)'
        stub_block = '''  }
} else {
  # Stub action when optimize_webui=false - declares same outputs as optimize_images
  # but without optimization. Copy Images.prebundle.js to Images.js.
  # The SVG files are generated by generate_css_vars, so we depend on that target
  # and declare the SVG outputs so other targets can depend on them.
  action("optimize_images") {
    _bundled_entrypoint = target_gen_dir + "/Images.prebundle.js"
    _output_file_location = target_gen_dir + "/Images.js"
    
    public_deps = [
      ":Images",
      ":generate_css_vars",
    ]
    
    # Copy Images.prebundle.js to Images.js (no optimization)
    script = "//third_party/devtools-frontend/src/front_end/Images/copy_file.py"
    args = [
      rebase_path(_bundled_entrypoint, root_build_dir),
      rebase_path(_output_file_location, root_build_dir),
    ]
    inputs = [ _bundled_entrypoint ]
    outputs = [ _output_file_location ]
    
    # Declare SVG outputs (they're generated by generate_css_vars dependency)
    foreach(svg_image, devtools_svg_sources) {
      outputs += [ "$target_gen_dir/$svg_image" ]
    }
    
    # Declare metadata with grd_files (same as optimize_images)
    metadata = {
      grd_files = [ _output_file_location ]
      foreach(svg_image, devtools_svg_sources) {
        grd_files += [ "$target_gen_dir/$svg_image" ]
      }
      foreach(_image_file, devtools_image_files) {
        grd_files += [ "$target_gen_dir/$_image_file" ]
      }
    }
  }
}

'''
        replacement = r'\1' + stub_block + r'\2'
        content = re.sub(pattern, replacement, content, count=1)
    
    with open(build_gn_path, 'w') as f:
        f.write(content)
    
    # Create copy_file.py script
    copy_py_path = os.path.join(os.path.dirname(build_gn_path), 'copy_file.py')
    os.makedirs(os.path.dirname(copy_py_path), exist_ok=True)
    with open(copy_py_path, 'w') as f:
        f.write('''#!/usr/bin/env python3
# Copyright 2024 The Chromium Authors
# Use of this source code is governed by a BSD-style license that can be
# found in the LICENSE file.

"""Simple script to copy a file for GN action."""

import shutil
import sys
import os

if len(sys.argv) != 3:
  print("Usage: copy_file.py <source> <destination>", file=sys.stderr)
  sys.exit(1)

source = sys.argv[1]
destination = sys.argv[2]

# Create destination directory if needed
os.makedirs(os.path.dirname(destination), exist_ok=True)

shutil.copy2(source, destination)
''')
    os.chmod(copy_py_path, 0o755)
    
    return 0

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print("Usage: apply-optimize-images-patch.py <BUILD.gn path>")
        sys.exit(1)
    
    sys.exit(apply_patch(sys.argv[1]))
